        internal static int[] UpperRanges, LowerRanges, TitleRanges, FoldRanges;
        internal static int[] UpperMultiLen, LowerMultiLen, TitleMultiLen, FoldMultiLen;
        internal static int[] UpperMultiOff, LowerMultiOff, TitleMultiOff, FoldMultiOff;
        // 256-code-point block index per map table: [lo, hi) range indices for that block. A map
        // table holds ~700 ranges over a million code points, so the plain binary search spent more
        // steps walking than comparing; a block slice is usually one or two entries.
        internal static int[] UpperIndex, LowerIndex, TitleIndex, FoldIndex;
        internal static int[] UpperMultiData, LowerMultiData, TitleMultiData, FoldMultiData;
        internal static int[] CasedRanges, CaseIgnorableRanges, UpperPropRanges,
                              LowerPropRanges, TitlePropRanges;
        // 128-entry direct tables: ASCII is the overwhelming majority of real text.
        private static readonly bool[] AsciiCased = new bool[128];
        private static readonly bool[] AsciiUpperProp = new bool[128];
        private static readonly bool[] AsciiLowerProp = new bool[128];
        private static readonly bool[] AsciiTitleProp = new bool[128];
        private static readonly bool[] AsciiIgnorable = new bool[128];

        private static int Read(System.IO.BinaryReader r) => r.ReadInt32();

        private static void LoadMapRanges(System.IO.BinaryReader r, out int[] table)
        {
            int n = Read(r);
            table = new int[n * 4];
            for (int i = 0; i < n * 4; i++) table[i] = Read(r);
        }

        private static void LoadMulti(System.IO.BinaryReader r, out int[] lens, out int[] offs, out int[] data)
        {
            int n = Read(r);
            lens = new int[n];
            offs = new int[n];
            var all = new List<int>();
            for (int i = 0; i < n; i++)
            {
                int k = Read(r);
                lens[i] = k;
                offs[i] = all.Count;
                for (int j = 0; j < k; j++) all.Add(Read(r));
            }
            data = all.ToArray();
        }

        private static void LoadRanges(System.IO.BinaryReader r, out int[] ranges)
        {
            int n = Read(r);
            ranges = new int[n * 2];
            for (int i = 0; i < n * 2; i++) ranges[i] = Read(r);
        }

        static UnicodeCaseData()
        {
            byte[] raw = Convert.FromBase64String(Blob);
            using var r = new System.IO.BinaryReader(new MemoryStream(raw));
            LoadMapRanges(r, out UpperRanges);
            LoadMulti(r, out UpperMultiLen, out UpperMultiOff, out UpperMultiData);
            LoadMapRanges(r, out LowerRanges);
            LoadMulti(r, out LowerMultiLen, out LowerMultiOff, out LowerMultiData);
            LoadMapRanges(r, out TitleRanges);
            LoadMulti(r, out TitleMultiLen, out TitleMultiOff, out TitleMultiData);
            LoadMapRanges(r, out FoldRanges);
            LoadMulti(r, out FoldMultiLen, out FoldMultiOff, out FoldMultiData);
            UpperIndex = BuildIndex(UpperRanges);
            LowerIndex = BuildIndex(LowerRanges);
            TitleIndex = BuildIndex(TitleRanges);
            FoldIndex = BuildIndex(FoldRanges);
            LoadRanges(r, out CasedRanges);
            LoadRanges(r, out CaseIgnorableRanges);
            LoadRanges(r, out UpperPropRanges);
            LoadRanges(r, out LowerPropRanges);
            LoadRanges(r, out TitlePropRanges);

            // Filled from the range tables directly: the public accessors consult these entries
            // first, so calling them here would read unset data.
            for (int cp = 0; cp < 128; cp++)
            {
                AsciiCased[cp] = FindRange(CasedRanges, 2, cp) >= 0;
                AsciiUpperProp[cp] = FindRange(UpperPropRanges, 2, cp) >= 0;
                AsciiLowerProp[cp] = FindRange(LowerPropRanges, 2, cp) >= 0;
                AsciiTitleProp[cp] = FindRange(TitlePropRanges, 2, cp) >= 0;
                AsciiIgnorable[cp] = FindRange(CaseIgnorableRanges, 2, cp) >= 0;
            }
        }

        /// <summary>Index of the inclusive range containing cp, or -1.</summary>
        private static int FindRange(int[] ranges, int stride, int cp)
        {
            int lo = 0, hi = ranges.Length / stride - 1;
            while (lo <= hi)
            {
                int mid = (lo + hi) / 2;
                int s = ranges[mid * stride];
                if (cp < s) { hi = mid - 1; continue; }
                if (cp > ranges[mid * stride + 1]) { lo = mid + 1; continue; }
                return mid;
            }
            return -1;
        }

        private static void AppendCp(StringBuilder sb, int cp)
        {
            if (cp <= 0xFFFF) sb.Append((char)cp);          // BMP, and unpaired surrogates
            else sb.Append(char.ConvertFromUtf32(cp));
        }

        private static int[] BuildIndex(int[] ranges)
        {
            const int shift = 8;
            const int size = 1 << shift;
            int blocks = (0x110000 + size - 1) >> shift;
            int total = ranges.Length / 4;
            var index = new int[blocks * 2];
            int r = 0;
            for (int b = 0; b < blocks; b++)
            {
                int blockStart = b << shift;
                int blockEnd = blockStart + size - 1;
                while (r < total && ranges[r * 4 + 1] < blockStart) r++;
                index[b * 2] = r;
                int hi = r;
                while (hi < total && ranges[hi * 4] <= blockEnd) hi++;
                index[b * 2 + 1] = hi;
            }
            return index;
        }

        private static bool Append(StringBuilder sb, int[] ranges, int[] index, int[] offs,
                                   int[] lens, int[] data, int cp)
        {
            int block = (cp >> 8) * 2;
            int found = -1;
            for (int i = index[block], stop = index[block + 1]; i < stop; i++)
            {
                if (cp >= ranges[i * 4] && cp <= ranges[i * 4 + 1]) { found = i; break; }
            }
            if (found < 0) { AppendCp(sb, cp); return false; }
            if (ranges[found * 4 + 3] == 0) { AppendCp(sb, cp + ranges[found * 4 + 2]); return true; }
            int idx = ranges[found * 4 + 2];
            int off = offs[idx];
            for (int k = 0; k < lens[idx]; k++) AppendCp(sb, data[off + k]);
            return true;
        }

        /// <summary>Append the FULL upper mapping of cp; true when the code point changed.</summary>
        public static bool AppendUpper(StringBuilder sb, int cp) =>
            Append(sb, UpperRanges, UpperIndex, UpperMultiOff, UpperMultiLen, UpperMultiData, cp);
        public static bool AppendLower(StringBuilder sb, int cp) =>
            Append(sb, LowerRanges, LowerIndex, LowerMultiOff, LowerMultiLen, LowerMultiData, cp);
        public static bool AppendTitle(StringBuilder sb, int cp) =>
            Append(sb, TitleRanges, TitleIndex, TitleMultiOff, TitleMultiLen, TitleMultiData, cp);
        public static bool AppendFold(StringBuilder sb, int cp) =>
            Append(sb, FoldRanges, FoldIndex, FoldMultiOff, FoldMultiLen, FoldMultiData, cp);

        public static bool IsCased(int cp) =>
            cp < 128 ? AsciiCased[cp] : FindRange(CasedRanges, 2, cp) >= 0;
        public static bool IsCaseIgnorable(int cp) =>
            cp < 128 ? AsciiIgnorable[cp] : FindRange(CaseIgnorableRanges, 2, cp) >= 0;
        public static bool IsUppercase(int cp) =>
            cp < 128 ? AsciiUpperProp[cp] : FindRange(UpperPropRanges, 2, cp) >= 0;
        public static bool IsLowercase(int cp) =>
            cp < 128 ? AsciiLowerProp[cp] : FindRange(LowerPropRanges, 2, cp) >= 0;
        public static bool IsTitlecase(int cp) =>
            cp < 128 ? AsciiTitleProp[cp] : FindRange(TitlePropRanges, 2, cp) >= 0;
    }
